 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extrapolate a diagonal sequence when two same-color markers define its direction.
    for color in set(v for row in grid for v in row):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        # Find a diagonal pair with the smallest step (adjacent consecutive markers).
        for r, c in pts:
            for dr, dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    rr, cc = nr+dr, nc+dc
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
                        rr += dr
                        cc += dc
    return out
